import type {ToolId} from "./tools";
import {planningContent} from "./planning-content";
import {phaseTwoContent} from "./phase-two-content";
import {phaseThreeContent} from "./phase-three-content";
export type ToolContent={formula:string;explanation:string[];example:string;tips:string[];sections:{heading:string;paragraphs:string[]}[];faq:{question:string;answer:string}[];sources:{title:string;url:string;checkedOn?:string}[];related:string[]};
const cfpb={title:"CFPB: Auto loan terms and disclosures",url:"https://www.consumerfinance.gov/consumer-tools/auto-loans/answers/key-terms/",checkedOn:"2026-10-15"};
const ftc={title:"FTC: Buying a used car from a dealer",url:"https://consumer.ftc.gov/articles/buying-used-car-dealer"};
const fuelSource={title:"DOE/EPA: Fuel economy and fuel costs",url:"https://www.fueleconomy.gov/feg/savemoney.jsp",checkedOn:"2026-10-15"};
export const toolContent:Record<ToolId,ToolContent>={
...planningContent,
...phaseTwoContent,
...phaseThreeContent,
loan:{formula:"P = max(0, price + financed sales tax + title + registration + other financed fees + old loan payoff − down payment − trade allowance)\nr = annual interest rate ÷ 1,200\nM = P × r ÷ (1 − (1 + r)^(−n))\nAt 0% interest: M = P ÷ n",explanation:["P is the amount you finance, r is the monthly interest rate, and n is the number of monthly payments. The calculator assumes one rate for the whole loan and payments at the end of each month. Interest is charged on what you still owe, and whatever is left of each payment goes to principal.","Each row of the schedule rounds interest and payment to cents, and the last installment clears the balance. Extra payments go to principal after that month's interest, so they can shorten the loan. The regular payment stays visible next to your extra amount so you can tell what's required from what's voluntary. If your down payment and trade credit cover the whole cost and the old loan, the financed amount is zero, and any leftover credit is shown separately rather than promised as a cash refund."],example:"A $25,000 car with $5,000 down, no trade, no financed fees and a 7% annual interest rate means a $20,000 loan. Over 60 months the estimated regular payment is $396.02. The 7% is an illustration, not a current offer. Adding $100 a month pays the balance down sooner and cuts the modeled interest.",tips:["Ask for a written out-the-door price before you pick a loan, and keep optional add-ons separate from the vehicle price.","Compare loans that finance the same amount. A lower monthly payment alone doesn't mean a lower total cost.","Ask whether extra payments go straight to principal and whether there's a prepayment charge.","Get a dated payoff quote for your trade. A statement balance can leave out accrued interest or fees."],sections:[{heading:"How do the rate and the loan term work together?",paragraphs:["APR and the contract interest rate are related, but they're not always the same number. APR folds in certain borrowing costs, while the monthly payment math needs the rate that actually accrues interest. Enter the contract rate if you have it. If you only know the APR, using it as the rate gives a rough answer, and it's less accurate when prepaid fees are large. Compare the lender's Truth in Lending disclosures before you sign.","A longer loan spreads the principal over more months, which usually lowers the required payment but raises total interest when the rate and amount stay the same. You also owe money for longer. Use the term comparison to decide whether a cheaper car or a bigger down payment beats stretching the repayment."]},{heading:"Why might my lender's schedule look different?",paragraphs:["Many auto loans charge simple interest daily, so the number of days between payments, the first due date, and paying early or late can all shift how a payment is split. This tool uses whole monthly periods, which makes it a budgeting estimate and not a payoff statement. Don't send a final payment based on the last row alone.","If your trade is worth less than you owe on it, the shortfall (negative equity) gets added to the new amount financed. That can leave you owing more than the new car is worth. Compare the new loan balance with a cautious resale estimate, and think about whether waiting would reduce that risk."]}],faq:[{question:"Can I calculate a 0% car loan?",answer:"Yes. At zero interest the principal is simply divided by the number of payments, and the last payment absorbs any rounding. Check whether taking a promotional rate means giving up a rebate."},{question:"Are sales tax and dealer fees included in the loan?",answer:"Only the dollar amounts you enter as financed sales tax, title, registration and other financed charges. Enter each cost once, and leave cash-paid charges out. The tax estimator can help you work out tax at a rate you've verified first."},{question:"Does an extra payment lower my regular payment?",answer:"No, not in this model. It lowers the balance and can shorten the loan. Lenders handle prepayments differently, so ask whether extra money is applied to principal only."},{question:"What happens if I owe more than my trade is worth?",answer:"The difference is added to the amount you finance. For example, a $5,000 trade with an $8,000 payoff adds $3,000 before any other purchase costs."},{question:"Is this a loan approval or a rate quote?",answer:"No. The tool doesn't check your credit, contact lenders or find offers. Eligibility and contract terms come from a real lender's decision."}],sources:[cfpb,{title:"CFPB: How amortization affects an auto loan",url:"https://www.consumerfinance.gov/ask-cfpb/what-is-amortization-and-how-could-it-affect-my-auto-loan-en-771/",checkedOn:"2026-10-15"}],related:["car-affordability-calculator","total-cost-of-ownership-calculator","car-sales-tax-calculator"]},
depreciation:{formula:"V₀ = starting value\nVₜ = V₀ × (1 − first decline/100) × (1 − annual decline/100)^(t−1)\nTotal depreciation = starting value − ending value",explanation:["The first decline is applied once, in the first year of your projection. The later decline then compounds on whatever value is left. A 12% annual decline takes fewer dollars off each year as the value shrinks. The chart and the table show the same calculation.","A used car doesn't start depreciating from scratch the day you buy it. Enter its current price or a value you can support as the starting point, then choose assumptions for the years you plan to own it. The default 18% and 12% declines are illustrative scenarios, not measured averages or forecasts for any make."],example:"Start with a $30,000 value and assume a 20% drop in the first projected year, then 10% a year after that. The modeled values are $24,000 after year one, $21,600 after year two and $19,440 after year three. Total modeled depreciation is $10,560. What you'd really get when you sell could be higher or lower.",tips:["Look at similar cars a few years older to see whether your residual value assumption is believable.","Run at least three scenarios instead of trusting one smooth curve.","Keep depreciation separate from your loan balance. Losing value and paying down principal are different things.","Count disposal costs or repairs separately when you estimate what you'd net from a sale."],sections:[{heading:"How do I pick assumptions for the car I'll actually own?",paragraphs:["Age alone doesn't explain price differences. Mileage, condition, accident history, service records, options, powertrain, supply and local demand all matter. A generic curve can't see a shortage, a discontinued model, a costly known problem or a change in new-car incentives, which is why the percentages are editable.","For a practical budget, start from the price you're likely to pay rather than the seller's first ask. Compare older examples with the same trim and a similar odometer reading. Listings are asking prices, not confirmed sales, but they can show when a proposed resale value is too optimistic."]},{heading:"How can the curve help me compare ownership periods?",paragraphs:["A one-year purchase is sensitive to transaction costs as well as lost value. Sales tax, registration, dealer fees and selling costs aren't included here. Keeping the car longer can spread those costs over more years, though maintenance exposure may grow. Send your chosen resale value to a full ownership-cost comparison before you decide.","With zero projected years, the result equals the starting value. A 100% first-year decline leaves a modeled value of zero. Negative rates aren't supported, so this tool doesn't model appreciation. If you're looking at a collectible or an unusual market, seek specialist comparables rather than forcing a standard curve to fit."]}],faq:[{question:"Are the default depreciation rates based on live prices?",answer:"No. They're plain planning assumptions. The tool has no listing feed, transaction database or appraisal connection behind it."},{question:"Which price should I enter for a used car?",answer:"Use its current value or the price you expect to pay. The first-year percentage then applies to the first year you own it, not to the year it was built."},{question:"Can a car lose more value than these estimates?",answer:"Yes. Condition, accidents, repairs, demand and local market conditions can cause losses that a smooth curve doesn't predict."},{question:"Does depreciation include loan interest?",answer:"No. Depreciation is just the starting value minus the ending value. Interest and running costs belong in a separate ownership-cost budget."},{question:"Why does the dollar loss shrink each year?",answer:"Because the yearly percentage is applied to a balance that keeps getting smaller. The same percentage of a smaller value is fewer dollars."}],sources:[ftc],related:["what-is-my-car-worth","total-cost-of-ownership-calculator","trade-in-value-estimator"]},
value:{formula:"Base = original base MSRP × 0.82 × 0.88^(age−1), for age ≥ 1\nMileage adjustment = clamp(−0.000002 × (miles − 12,000 × age), −0.20, +0.20)\nPrivate midpoint = base × (1 + mileage adjustment) × condition × trim\nTrade midpoint = private midpoint × 0.85; retail midpoint = private midpoint × 1.15\nEach scenario range = midpoint × [0.85, 1.15]",explanation:["At age zero the base equals the original base MSRP. After that, this illustrative curve assumes an 18% loss in the first year and 12% a year later on. It treats 12,000 miles a year as expected, and each mile above or below that benchmark adjusts the modeled value by 0.0002%, capped at 20% in either direction.","Condition multipliers are 1.05 for excellent, 1.00 for good, 0.85 for fair and 0.65 for poor. Trim multipliers are 1.00 for base, 1.05 for mid and 1.10 for premium. These are UNVERIFIED modeling assumptions, not observed premiums. If you pick a higher trim, start from the base model's original MSRP so you don't count the trim premium twice."],example:"A $30,000 original base price, five years old, 60,000 miles, good condition and base trim gives an illustrative private-sale midpoint of about $14,752. The trade midpoint is about $12,540 and the retail midpoint about $16,965. The ±15% bands are scenario ranges, not confidence intervals or prices anyone has promised to pay.",tips:["Check several similar local cars with the same model, year, trim, powertrain and mileage.","Treat advertised prices as asking prices, and record actual written offers separately.","Tell buyers about known damage and title brands. A generic condition dropdown can't price them reliably.","If you need a valuation for insurance, an estate, a lender or a legal matter, get a professional appraisal."],sections:[{heading:"What can this estimate tell me, and what can't it?",paragraphs:["The calculator shows how age, usage and a broad idea of condition affect a transparent baseline. It can't identify a specific car, inspect it, confirm a title or see what a buyer would really pay. There's no VIN decoding, licensed valuation feed, dealer inventory or live sales data behind it, and cars with the same MSRP can resell very differently.","Dealer retail, private sale and trade-in are three different transactions. A dealer pays for reconditioning, selling, inventory and overhead. A private buyer may weigh records and condition differently. The fixed channel adjustments here only illustrate that gap; they aren't a claim that any dealer's margin is unfair."]},{heading:"How do I turn a broad range into real evidence?",paragraphs:["Write down your car's exact specification and its true mileage. Collect service invoices, title information and photos of any known issues. Compare asking prices for similar cars, and ask for several written offers using the same disclosures. If those offers land far from the model, the offers matter more than the generic curve.","If you're deciding whether to sell, separate the price from what you'll actually keep. Subtract your loan payoff, preparation costs, inspection costs and any selling fees. A higher private-sale price can cost you time and effort. Compare that net amount with a real trade offer, not one channel's midpoint with another channel's best case."]}],faq:[{question:"Does this use live market data?",answer:"No. It uses only the age, mileage, condition and trim model described above, so the results are educational estimates and not appraisals."},{question:"Why can't I enter a make or VIN?",answer:"Because no vehicle-specific database is connected. Asking for a VIN would suggest precision the model doesn't have, and it would collect information it doesn't need."},{question:"What do the value ranges mean?",answer:"Each range runs 15% below and above its modeled midpoint. It's an illustrative uncertainty band, not a statistically validated prediction interval."},{question:"Can I enter mileage in kilometers?",answer:"Yes. The calculator converts kilometers to miles using 1 mile = 1.609344 kilometers before it applies the mileage assumption."},{question:"How should I choose the condition setting?",answer:"Be cautious and honest. Real damage, unusual modifications or title brands call for an inspection and market evidence, because a dropdown can't capture them."}],sources:[ftc,{title:"NMVTIS: Consumer vehicle-history information",url:"https://vehiclehistory.bja.ojp.gov/"}],related:["trade-in-value-estimator","car-depreciation-calculator","used-car-price-negotiation-calculator"]},
ownership:{formula:"Total cost = purchase price − resale value\n  + years × (annual fuel + insurance + maintenance + recurring fees)\n  + upfront taxes/fees + interest paid during ownership\nAnnual fuel = annual miles ÷ US mpg × price per US gallon",explanation:["This is an economic ownership-cost model. Paying for the car buys you an asset, and depreciation measures how much of its value you use up. If you counted the full purchase price or every principal payment on top of depreciation, you'd count the car twice. So the model includes depreciation and financing interest as separate items.","Fuel, insurance, maintenance and recurring taxes or registration go in as yearly averages. Upfront purchase fees are added once and assumed paid in cash. Interest comes from the modeled loan schedule for your chosen ownership period only. If the loan runs longer than that, the leftover balance is shown so you can plan the sale."],example:"Say you buy a $20,000 car with cash and sell it for $10,000 after five years. Depreciation is $10,000. At 12,000 miles a year, 30 US mpg and $3 a gallon, fuel totals $6,000. Add $6,000 insurance, $3,000 maintenance, $500 recurring fees and $1,000 upfront costs, and the total economic cost is $26,500, or about $442 a month.",tips:["Get insurance quotes for the exact car before you agree on a price.","Set your repair reserve from the car's history instead of assuming every year will look the same.","Compare cars over the same years and miles, or the totals answer different questions.","Stress-test a lower resale value and a higher repair budget together."],sections:[{heading:"What goes into a realistic set of inputs?",paragraphs:["Use a price you expect to negotiate and a cautious resale estimate. Put sales tax, title costs and cash-paid acquisition fees in the upfront field, and don't include them again in the purchase price. For recurring fees, use the registration or vehicle taxes you expect to pay each year. The calculator doesn't infer state rules.","The default fuel price and insurance are examples, not current averages or quotes. Real fuel use shifts with traffic, weather, trip length, driving style and load. An annual repair allowance is a reserve, not a forecast that repairs will arrive evenly. If a big service is already due, include it instead of smoothing it away."]},{heading:"Why do economic cost and cash flow answer different questions?",paragraphs:["The average monthly figure helps you compare cars, but it isn't a monthly bill. A down payment and fees may be due right away, repairs show up unevenly, and resale money only arrives when you sell. Keep an emergency fund, and check separately that the loan payment and running costs fit your household cash flow each month.","The model leaves out inflation, investment returns on cash, parking, tolls, charging, business tax deductions and unusual disposal costs unless you build them into an annual allowance. If resale is higher than the purchase price, depreciation goes negative, so look hard at that assumption. With zero annual distance, you'll get no per-mile estimate rather than a divide-by-zero error."]}],faq:[{question:"Why isn't the whole loan payment added to the total?",answer:"Because the principal you repay changes your debt and your equity, and depreciation already counts the vehicle value you use up. In this model only the interest is an extra financing cost."},{question:"Does the down payment change the total?",answer:"Yes, through interest, because it changes how much you borrow. With a zero-rate loan and nothing else changed, moving principal between cash and borrowing doesn't change economic cost."},{question:"What if I sell the car before the loan ends?",answer:"The tool counts interest during ownership and shows the balance still owed. The sale proceeds may have to settle that balance, but that isn't another depreciation expense."},{question:"Are the maintenance estimates reliable predictions?",answer:"No. Set a reserve based on inspection findings and the car's service needs, then test higher-cost scenarios. Real repairs come in lumps and are hard to predict."},{question:"Can this compare electric vehicles?",answer:"Not accurately. The fuel model uses US mpg and liquid-fuel prices and doesn't calculate kWh use, so don't treat its fuel result as an EV charging estimate."}],sources:[fuelSource,cfpb,ftc],related:["car-loan-calculator","fuel-cost-calculator","car-depreciation-calculator"]},
affordability:{formula:"Payment budget = max(0, min(0.10 × gross income − running costs,\n  0.36 × gross income − other debts − running costs))\nFinance capacity = payment budget ÷ payment on $1 financed for 48 months\nPurchase budget = min(down payment ÷ 0.20, down payment + finance capacity)",explanation:["The calculation applies three illustrative limits together: at least 20% down, a 48-month loan, and total car expenses within 10% of gross monthly income. A fourth rule caps your other debt plus car expenses at 36% of gross income. That cap is a planning assumption, not a lender's underwriting standard.","Monthly running costs come out first, before the calculator works out how much payment is left for financing. The smaller of the cash-down limit and the payment-supported limit sets your purchase budget. If no payment room remains, the result may still show your cash as a cash-purchase budget, which doesn't mean the ongoing expenses are affordable."],example:"With $6,000 of gross monthly income, $700 of other debt payments, $5,000 down and $250 of monthly running costs, the 10% guideline leaves $350 for a loan payment. At a 7% annual rate over 48 months, that supports about $14,618 of financing. Your total purchase budget comes to about $19,618 before you separate taxes and fees from the car's price.",tips:["Put insurance, fuel, routine service, repair reserves, parking and recurring registration in the running costs.","Use reliable income, not your best commission month or uncertain overtime.","Keep the down payment apart from your emergency fund and cash for immediate repairs.","Recheck the result against take-home pay, housing costs, family needs and savings goals."],sections:[{heading:"Is a rule of thumb enough to decide?",paragraphs:["It's a good place to start, nothing more. Gross income makes comparisons easy, but taxes and deductions decide what actually lands in your account, and two households with the same salary can have very different room for a car. Childcare, medical bills, housing, support payments and uneven income don't show up in a simple percentage. Use the result to narrow your search, then build a full cash-flow budget.","The 20/4/10 framework isn't a law, a guarantee of good financial outcomes or a promise of loan approval. Some buyers can comfortably spend less, and others can't cover necessary transport within the percentage. If you fall short, that's useful to know: consider a cheaper car, a bigger down payment you can truly afford, or waiting."]},{heading:"How do I work backward from the complete purchase?",paragraphs:["Treat the result as a total acquisition budget, not a listing-price target. If your budget is $20,000 and verified taxes and fees come to $1,500, a $20,000 sticker price doesn't fit. Leave room for the inspection, immediate service and other costs you want to pay without borrowing.","A higher interest rate shrinks the amount a fixed payment can finance. Stretching the term can hide that pressure inside a low monthly bill while adding interest and prolonging the risk of owing more than the car is worth. This tool keeps the loan at 48 months on purpose; use the car loan calculator to see the tradeoff yourself instead of quietly changing the guideline."]}],faq:[{question:"Is 20/4/10 an official lending rule?",answer:"No. It's a budgeting guideline, and this calculator applies it with the assumptions stated above. Lenders use their own criteria and may approve amounts that would be uncomfortable for your household."},{question:"Why is the budget zero if I have no down payment?",answer:"Because this version requires at least 20% down. With no down payment, that rule can't be met for any positive price, even if your income could support payments."},{question:"Should I enter take-home or gross income?",answer:"Gross monthly income, because that's what the model uses. Then check the payment it suggests against your take-home pay before relying on the budget."},{question:"Does the result include insurance?",answer:"Only through the monthly running-cost amount you enter. Get an actual quote and update that number, since the tool doesn't estimate insurance rates."},{question:"What is the 36% limit?",answer:"It's an extra illustrative cap on your other debt payments plus modeled car spending. It isn't a standard debt-to-income calculation or an approval threshold."}],sources:[cfpb,{title:"CFPB: Compare auto loan offers",url:"https://www.consumerfinance.gov/ask-cfpb/how-do-i-compare-auto-loan-offers-what-should-i-look-at-besides-the-monthly-payment-en-753/"}],related:["car-loan-calculator","total-cost-of-ownership-calculator","car-sales-tax-calculator"]},
fuel:{formula:"US gallons used = miles ÷ miles per US gallon\nLiters used = kilometers × liters per 100 km ÷ 100\nFuel cost = fuel used × price per matching volume unit\n1 US gallon = 3.785411784 liters; 1 mile = 1.609344 kilometers",explanation:["In US mode, efficiency is miles per US gallon, so a bigger number means less fuel for the same distance. In metric mode it's liters per 100 kilometers, so a smaller number means less fuel. Switching units converts the distance, fuel price and efficiency together, with small rounding differences.","The trip estimate and the annual estimate use the same fuel economy and price but separate distances. Monthly spending is the annual estimate divided by twelve. That lets you budget one particular trip without assuming you take it every day. Money stays in USD in either unit system."],example:"A 300-mile trip in a car that averages 30 US mpg burns about 10 US gallons. At an illustrative $3.50 a gallon, that's $35 in fuel. Drive 12,000 miles a year on the same numbers and fuel runs $1,400 a year, or about $117 a month. These are arithmetic examples, not today's pump prices.",tips:["Use your own long-run fuel economy when you have it, not a best-case dashboard reading.","For a round trip, count the drive home and your normal local driving too.","Try a higher fuel price or worse economy for winter weather, city traffic, towing or heavy loads.","Keep parking, tolls, lodging and wear costs separate when you compare ways to travel."],sections:[{heading:"How do I make the estimate match my driving?",paragraphs:["Official fuel-economy ratings are a good starting point for comparing cars, but real driving differs from the test cycle. Short trips, cold starts, traffic, speed, tire condition, cargo and hills all change how much fuel you use. If you track trip distance and fuel added across several fill-ups, that longer record is usually a better input than one good trip.","Don't mix imperial mpg with US mpg. An imperial gallon is bigger, so the same car shows a different mpg figure. This tool uses US gallons and liters only, so convert imperial numbers before entering them. The kilometers setting changes units; it doesn't look up Canadian or UK fuel prices."]},{heading:"How do I compare efficiency in dollars?",paragraphs:["The link between mpg and fuel use isn't a straight line. Over the same distance, going from 20 to 25 mpg saves more gallons than going from 40 to 45. Enter both scenarios and save one for comparison to see the real spending difference. Fuel savings are only part of choosing a car, and an expensive upgrade may take many years to pay for itself that way.","The sensitivity table moves the pump price 20% above and below your input while distance and efficiency stay fixed. It's a what-if comparison, not a forecast. For a full budget, add maintenance, depreciation, insurance and financing in the ownership-cost calculator. Electric charging and plug-in hybrids need their own energy models and are outside this tool."]}],faq:[{question:"Are fuel prices updated automatically?",answer:"No. Enter a pump price or a planning assumption. The default is only an illustration and isn't described as a current national or local average."},{question:"Does metric mode change the currency?",answer:"No. It changes distance, consumption and volume units. Prices and results stay in USD, so convert to a USD-equivalent price if you need to."},{question:"Why did my numbers change when I switched units?",answer:"Distance, efficiency and price are converted so the scenario stays roughly the same. Rounding can cause a small difference in the cost you see."},{question:"Can I enter zero miles?",answer:"Yes. A zero-distance trip costs zero. Efficiency does have to stay above zero so the fuel consumption means something."},{question:"Does this estimate electric charging costs?",answer:"No. It models liquid fuel only. Electric cars need kWh use, charging losses and electricity prices instead of mpg."}],sources:[fuelSource],related:["total-cost-of-ownership-calculator","car-affordability-calculator","car-depreciation-calculator"]},
trade:{formula:"Private midpoint = age-depreciated original base MSRP × mileage × condition × trim adjustments\nTrade midpoint = private midpoint × 0.85\nTrade scenario band = midpoint × [0.85, 1.15]\nNet trade equity = estimated trade value − current loan payoff",explanation:["The valuation underneath is illustrative. It starts with an 18% decline in the first year and 12% in each year after, and at age zero it keeps the starting MSRP. It treats 12,000 miles a year as expected, with an adjustment of 0.0002% per mile above or below that and a cap of ±20%. Kilometers are converted first.","Good condition and base trim both have a 1.00 multiplier. Excellent, fair and poor condition use 1.05, 0.85 and 0.65, and mid and premium trim use 1.05 and 1.10. The trade midpoint is 85% of the private midpoint. Every coefficient here is a modeling choice, not a measured dealer discount or a licensed valuation."],example:"For a five-year-old car with a $30,000 original base MSRP, 60,000 miles, good condition and base trim, the modeled trade midpoint is about $12,540. With an $8,000 payoff, midpoint equity is about $4,540. If a real dealer offers $11,000, that real offer replaces the modeled amount in your purchase budget.",tips:["Collect written offers close together in time, and give each buyer the same condition details.","Keep the new car's price, the trade allowance, the loan payoff and the financing as separate lines.","Ask your lender for the payoff amount and how they confirm the old loan is closed.","Check any trade-related tax treatment with your state's authority instead of assuming it applies."],sections:[{heading:"Is the trade allowance the whole story?",paragraphs:["No, it's one line in the deal. A generous-looking allowance can be offset by a higher price on the new car, added products or worse financing. Compare complete written deals on the same car and the same assumptions. Write down the price before trade, taxes and fees, the trade allowance, the payoff, cash down, amount financed, rate and term. Talking only about the monthly payment hides those tradeoffs.","The range shown is ±15% around a generic midpoint. It doesn't mean a dealer will buy within that band. Reconditioning needs, title history, local inventory, demand and the specific model can matter more than anything here. A dealer's inspection and written offer are evidence this tool doesn't have."]},{heading:"What if I have positive or negative equity?",paragraphs:["Positive equity means the offer is more than you owe, which leaves value you can put toward the next car. Negative equity means you owe more than the offer. Rolling that gap into a new loan raises the new principal, but it doesn't make the old debt go away. You can model that directly in the loan calculator.","A private sale may bring in more, but it also takes preparation, advertising, appointments, safe payment and coordination of the lien release. Compare what you'd net and the effort involved, not just the highest price you saw online. Before handing over keys or title, confirm the transfer steps with your lender and your state motor-vehicle agency, and keep proof that the old loan was paid."]}],faq:[{question:"Is this a guaranteed cash offer?",answer:"No. There's no dealer network or live offer behind it. It's a planning model that gives you a broad range and a rough idea of equity."},{question:"Why is the trade-in value lower than the private-sale value?",answer:"The model applies an illustrative 15% reduction for the trade-in channel. That's a scenario, not a fixed margin that every dealer or vehicle follows."},{question:"Can a trade-in increase my next loan?",answer:"Yes. If your payoff is more than the trade allowance, the difference has to be paid or financed. The loan calculator shows what that does to your payment and interest."},{question:"Does the estimate include a tax saving?",answer:"No. Tax treatment depends on the transaction and where you live. Enter only a verified allowed credit in the separate sales tax calculator."},{question:"What should I use as the payoff amount?",answer:"A payoff quote from your lender that's valid for the date you expect to close. A statement balance may not include all accrued interest or charges."}],sources:[cfpb,ftc],related:["what-is-my-car-worth","car-loan-calculator","car-sales-tax-calculator"]},
lease:{formula:"Buy equity at end = resale value − remaining loan balance\nBuy net cost = down payment + loan payments made − end equity\nLease total = extra upfront cash + monthly payment × comparison months\n  + other lease fees + total excess miles × per-mile charge",explanation:["Both options are compared over the same period, which should match the lease term you were quoted. Buying assumes you sell the car at the end and recover the equity. If the loan balance is more than the resale value, the equity is negative and raises the modeled cost of buying. A paid-off car still has a residual value.","The lease inputs start from the monthly payment you were actually quoted, instead of trying to work backward from a money factor. Include monthly tax in that payment. Extra upfront cash leaves out the first monthly payment, since every installment is already counted; otherwise it would be counted twice. Leave out refundable deposits."],example:"Buy a $20,000 car with $2,000 down and a zero-rate, 60-month loan. After 36 months you've paid $10,800 and owe $7,200. If it's worth $12,000, your equity is $4,800 and buying costs you $8,000 net. A lease at $250 a month for 36 months, plus $1,000 upfront, $300 in fees and $250 in mileage charges, costs $10,550.",tips:["Compare similar cars over the same horizon. A three-year lease and five years of buying answer different questions.","Read the lease's mileage allowance, excess-mile charge, wear rules and end-of-term fees.","Include taxes the same way on both sides, and make sure acquisition or disposition fees aren't counted twice.","Run a lower resale scenario for buying and a higher-mileage scenario for leasing."],sections:[{heading:"Why is cash paid different from cost?",paragraphs:["Buying may mean bigger monthly payments, but you end up with an asset. Leasing usually leaves you with no equity unless you buy the car separately. Just adding up payments and comparing the sums misses that. This model takes estimated end equity off the cash you paid to buy, so the comparison reflects the value you keep.","The resale estimate is uncertain, and it can change which option wins. If you plan to keep the car rather than sell it, that equity isn't cash in your pocket, even though it's part of your net position. Look at both the economic cost and the actual cash you'd have to spend during the term."]},{heading:"What lease details should I keep in view?",paragraphs:["This calculator doesn't judge whether a lease's money factor, residual, acquisition charge or early-termination terms are reasonable. Enter the full written quote, including taxes and fees, and read the restrictions before you compare. An advertised payment may leave out upfront amounts, tax or eligibility conditions that change the total a lot.","Fuel, insurance, maintenance, repairs and the opportunity cost of your money are left out of both columns. If those differ between the two cars, the gap you see is incomplete. A new leased car and an older used car may come with different warranties and repair exposure, so list those differences separately or use the ownership-cost scenarios alongside this one."]}],faq:[{question:"Does this work out a lease payment from a money factor?",answer:"No. Enter the payment from a written quote. The tool compares total costs over an equal period and doesn't create a lease offer."},{question:"Should the first month's payment go in the upfront cash field?",answer:"No. The monthly payment is multiplied by the full comparison term, so enter only the extra nonrefundable upfront cash. Otherwise the first payment is counted twice."},{question:"What if my loan runs longer than the lease?",answer:"The balance still owed at the comparison date is subtracted from the resale value to get your equity. The calculator doesn't assume the rest of the loan disappears for free."},{question:"Does the comparison include a lease-end buyout?",answer:"No. It assumes you return the leased car. Buying it out at the end needs a separate look at the purchase price, fees, taxes and financing."},{question:"Does the lower result tell me which to choose?",answer:"It shows which option is cheaper under your inputs. Mileage flexibility, how long you want to keep the car, contract restrictions and uncertain running costs still matter."}],sources:[cfpb,{title:"FTC: Financing or leasing a car",url:"https://consumer.ftc.gov/articles/financing-or-leasing-car"}],related:["car-loan-calculator","total-cost-of-ownership-calculator","car-affordability-calculator"]},
inspection:{formula:"Recorded progress = (checked + concerns + not applicable) ÷ 25 × 100\nConcern count = number of items marked Concern\nProgress is record completion, not a safety score.",explanation:["The checklist has 25 prompts in five groups: identity and paperwork, exterior and tires, cabin and controls, mechanical observations, and the test drive. Every item starts as not checked. Mark it checked only after you've actually looked at the evidence. Mark it a concern if it needs follow-up, or not applicable if it doesn't fit this car.","Progress counts every decision you've recorded, concerns included. Reaching 100% doesn't mean the car passed an inspection; it means you've given every prompt a status. Your mechanic can start from the items you flagged, but a professional inspection should go well beyond this consumer checklist."],example:"Suppose you record 12 checked items, three concerns and two not-applicable items. That's 17 of 25, or 68% progress, and the summary shows three concerns. Before committing, work through those concerns and look into the eight items still unchecked. Printing the summary helps you keep a consistent set of notes as you look at several cars.",tips:["Plan for daylight, a safe location, the seller's permission and enough time before you arrive.","Ask to see a cold start if you can, and keep your hands away from hot or moving parts.","Never get under a car held up only by an emergency jack.","Pay for an independent inspection and ask for the findings in writing before you decide."],sections:[{heading:"Where should I start: the car or the paperwork?",paragraphs:["Start with identity and records. Match the VIN on the car to the title, the listing and the service documents. Check that the seller has the right to sell it, and clear up any lien before money changes hands. Look at available vehicle-history information and search for recalls. A history report can't prove every accident or repair was reported, and a recall search doesn't tell you the car's current mechanical condition.","If you're buying from a dealer, read the Buyers Guide and understand whether the car comes with a warranty or is sold as is. Get repair promises and other important statements in writing. If the dealer won't allow a reasonable independent inspection, you have less to go on, even if the car looks clean or the listing calls it certified."]},{heading:"How can I look at a car safely, then bring in an expert?",paragraphs:["On the walkaround, note mismatched panels, rust, tire wear, broken lights, water marks and odd smells, without jumping to a diagnosis. On a test drive you're allowed to take, pay attention to ordinary braking, steering, transmission behavior and warning lights on a safe route. Skip aggressive maneuvers or tests you aren't qualified to do.","A concern is a question to chase down, not automatically a defect or a bargaining chip. Ask an independent mechanic what's causing it, how serious it is, how urgent it is, and for a written repair estimate. Structural damage, safety systems, flood exposure and high-voltage parts may call for specialists. An unresolved major issue can be a good reason to pause rather than just negotiate a lower price."]},{heading:"What should I keep private when I share my notes?",paragraphs:["A share link stores only the checklist statuses in the URL. It doesn't upload a VIN, seller details, photos or a vehicle report. Anyone with the link can see those statuses, so keep private supporting documents somewhere else. Download your findings for your own records, and start a fresh checklist for each car you look at."]}],faq:[{question:"Does a completed checklist mean the car is safe?",answer:"No. Completion only shows how many observations you've recorded. It isn't a certification or a mechanical diagnosis, and it doesn't replace an independent inspection."},{question:"Will my checklist survive a page reload?",answer:"Yes, as long as you reload the same URL. The statuses are stored in the page address, so reloading it or opening a copied link restores them, and Reset clears them."},{question:"Can I share the checklist with a mechanic?",answer:"Yes. Copy the result link, print the page or download the findings. Send private supporting documents separately by a method you trust."},{question:"What should I do about a concern?",answer:"Ask for an explanation and independent evidence, and get a written repair estimate when it makes sense. Don't go ahead while questions about identity, title or serious safety issues remain unresolved."},{question:"Does a clean history report replace an inspection?",answer:"No. History databases can be incomplete and say nothing about the car's current mechanical condition. Use the report, the service records, a recall check and an independent inspection together."}],sources:[ftc,{title:"NHTSA: Check vehicle recalls",url:"https://www.nhtsa.gov/recalls"},{title:"NMVTIS: Vehicle-history resources",url:"https://vehiclehistory.bja.ojp.gov/"}],related:["used-car-price-negotiation-calculator","what-is-my-car-worth","total-cost-of-ownership-calculator"]},
negotiation:{formula:"Vehicle-price ceiling = supported comparable value − repair deductions\nOpening offer = ceiling × (1 − chosen discount/100)\nOffer with entered fees = opening offer + known taxes and fees",explanation:["Start with a comparable value you can explain: same year, model, trim, powertrain, similar mileage and condition, in your local market. The calculator doesn't fetch comparable sales or check your number. Take off documented repair costs only if the baseline doesn't already reflect those same problems.","You choose the opening discount. The default 5% is there to show the math; it isn't evidence of a typical negotiating margin. The ceiling is a reference point after repairs, and known taxes and fees are added separately so the offer isn't mistaken for the full price of the transaction."],example:"A supported $20,000 comparable value minus $1,000 of repairs gives a $19,000 ceiling. A 5% opening discount makes the opening offer $18,050. Add $500 in known fees and you're at $18,550, before any taxes or costs not covered by that fee input. The seller can accept, counter or say no.",tips:["Bring specific comparable listings and explain real differences, instead of leaning on a broad average.","Back up repairs with written inspection findings, and don't subtract the same problem twice.","Ask for an itemized out-the-door total, and look at optional products separately.","Set a walk-away budget before you start, and leave room for early maintenance."],sections:[{heading:"What evidence should I gather before choosing a number?",paragraphs:["An opening offer holds up better when it follows evidence. Note each comparable car's specification, mileage, asking price, location and any known fees. A listing that leaves out important charges isn't directly comparable with an all-in offer. Asking prices also don't prove what buyers ended up paying, so don't present them as confirmed sales.","Repairs need context. A safety repair you need right away, routine service that's due soon and a cosmetic preference are three different things. A car already priced as rough may not justify subtracting every restoration cost from a clean-car value without more adjustment. If the repairs add up to more than the whole comparable value, this tool won't run the calculation and asks you to rethink it."]},{heading:"Should the price decide whether I buy?",paragraphs:["Not by itself. A lower price doesn't fix an unclear title, suspected structural damage, mileage you can't verify or a seller who won't allow an inspection. Those can change whether you should buy at all. Treat the ceiling as a planning reference, not a command to buy if the seller meets it. Your household budget and other cars you could buy still matter.","The tool takes one combined amount for known taxes and fees, but some taxes change with the final agreed price. Recalculate them and review the final written deal before you sign. Keep the new car's price, trade allowance, old loan payoff, optional products and loan terms separate. Negotiating only the payment can hide increases elsewhere in the deal."]}],faq:[{question:"Is a 5% discount usually achievable?",answer:"The calculator makes no such claim. The 5% is an editable scenario input. How flexible a seller is depends on the car, the competition, demand and whether the asking price is supported."},{question:"Where should the comparable value come from?",answer:"From relevant local evidence, and from real offers where you can get them. Match the key characteristics of the car, and keep asking prices separate from completed sales."},{question:"Should I deduct every inspection finding?",answer:"No, only a supported adjustment that isn't already in the baseline. Some findings change whether you should buy rather than just producing a repair discount."},{question:"Are taxes recalculated automatically?",answer:"No. Enter the known taxes and fees, and refresh them whenever the agreed price changes. The sales tax calculator can help if you have a verified rate and taxable base."},{question:"Does the ceiling replace my personal budget?",answer:"No. Your maximum should also reflect what you can afford, immediate repairs and the alternatives available. A modeled market ceiling can be higher than what you can comfortably spend."}],sources:[ftc,cfpb],related:["used-car-inspection-checklist","car-sales-tax-calculator","car-affordability-calculator"]},
tax:{formula:"Taxable base = vehicle price + taxable fees − verified allowed credit\nEstimated tax = taxable base × combined rate/100\nPurchase total = vehicle price + taxable fees + tax + nontaxable fees\nTrade payment, loan payoff, and down payment are handled separately.",explanation:["Enter the rate that applies to your transaction after you've confirmed it with the relevant authority. The 6% default is a math example and isn't any state's rate. The state selector only points you to official agency pages. It doesn't know your address, tax district, residency, type of sale, exemptions or current law.","The allowed credit lowers the taxable base. It isn't a cash payment in the purchase total. A trade-related tax credit and the trade allowance you use to settle the deal are related, but they're different line items. Subtract the actual allowance separately when you work out what you have to pay or finance."],example:"Take a $20,000 car, $500 in taxable fees, a verified $5,000 allowed tax-base credit and an illustrative 6% rate. The taxable base is $15,500 and the tax is $930. With $200 in nontaxable fees, the purchase total before trade payment and down payment is $21,630. The example doesn't show that any jurisdiction allows those inputs.",tips:["Check the rules for where the car will be titled or registered, and for your type of transaction.","Ask which dealer charges are taxable and whether the same rate applies to each.","Find out whether trade allowances, rebates, private sales or exemptions change the tax base.","Get an itemized list in writing and compare it with the authority's official calculator or instructions."],sections:[{heading:"Why isn't a state name enough?",paragraphs:["Vehicle tax can depend on state and local rules, where you live, whether you buy from a dealer or a private seller, the vehicle type, and how a trade is handled and when. Some places use different taxes, ways of measuring value, caps or exemptions. A single statewide percentage can give a misleading answer for your purchase.","That's why this tool asks for a combined rate and allowed credit that you've verified, instead of keeping an unchecked table of current rates. The directory is meant to get you to official information, but the right calculation may take a local office or another authority. Read the agency's own instructions and effective dates, not a search snippet or an old dealer estimate."]},{heading:"When does the simplified model not fit?",paragraphs:["The formula applies one percentage to one taxable base. It can't handle tax caps, brackets, separately taxed charges, use-tax credits for another jurisdiction, unusual valuation rules or conditional rebates. If any of those apply, use the authority's method and treat this result as a partial illustration. The tool rejects a credit larger than the taxable amount instead of inventing a refund.","An out-the-door total also needs the actual title, registration, plate, inspection and dealer charges in your deal. Enter only fees you've verified, and don't assume a charge is nontaxable just because it's on its own line. When the price changes during negotiation, work out the tax again and look through the final paperwork for duplicate or optional charges."]}],faq:[{question:"Does selecting a state fill in its tax rate?",answer:"No. It links to an official agency resource. You still need to enter and verify the rate and any allowed credit for your own transaction."},{question:"Is the default 6% a current state rate?",answer:"No. It's a made-up example. Replace it before you use the result to plan a real purchase."},{question:"Does every state allow a trade-in tax credit?",answer:"This tool doesn't claim that. Check whether a credit applies where you live, how much is allowed and whether the transaction has to meet certain conditions."},{question:"Why isn't my trade-in subtracted from the purchase total?",answer:"Because the credit you enter only changes the tax calculation. The actual trade allowance is a separate payment toward the deal and belongs in the loan or settlement math."},{question:"Can I use this for a UK or Canadian purchase?",answer:"The arithmetic works anywhere, but this page's resources and assumptions are US-focused. It doesn't apply UK or Canadian tax rules, currencies or regional requirements."}],sources:[{title:"USA.gov: State motor-vehicle services",url:"https://www.usa.gov/state-motor-vehicle-services"},{title:"Texas Comptroller: Motor vehicle tax",url:"https://comptroller.texas.gov/taxes/motor-vehicle/"},{title:"California DMV: Vehicle registration fees",url:"https://www.dmv.ca.gov/portal/vehicle-registration/registration-fees/"}],related:["car-loan-calculator","used-car-price-negotiation-calculator","trade-in-value-estimator"]},
};
